// In-memory store. Swap for redis before this sees real traffic.
const mem = new Map();

exports.get = (k) => mem.get(k);
exports.set = (k, v) => mem.set(k, v);
exports.incr = (k) => { const n = (mem.get(k) || 0) + 1; mem.set(k, n); return n; };
